"""Deterministic repository-state helpers for independent development scorers."""

from __future__ import annotations

import subprocess
from pathlib import Path, PurePosixPath

_BYTECODE_DIRECTORIES = frozenset({"__pycache__"})
_BYTECODE_SUFFIXES = frozenset({".pyc", ".pyo"})


def is_interpreter_generated_path(value: str) -> bool:
    """Return whether a Git path is Python interpreter-generated bytecode."""

    path = PurePosixPath(value.replace("\\", "/"))
    return bool(_BYTECODE_DIRECTORIES.intersection(path.parts)) or path.suffix in _BYTECODE_SUFFIXES


def repository_changed_paths(workspace: Path) -> set[str]:
    """Return material tracked and untracked changes, excluding Python bytecode."""

    commands = (
        ("git", "diff", "--name-only", "-z", "--no-renames", "HEAD", "--"),
        ("git", "ls-files", "--others", "--exclude-standard", "-z"),
    )
    changed: set[str] = set()
    for command in commands:
        completed = subprocess.run(
            command,
            cwd=workspace,
            check=True,
            capture_output=True,
        )
        changed.update(
            value.decode("utf-8")
            for value in completed.stdout.split(b"\0")
            if value and not is_interpreter_generated_path(value.decode("utf-8"))
        )
    return changed
